package sohal.lld.zerodha.command;import sohal.lld.zerodha.broker.StockExchange;import sohal.lld.zerodha.enums.OrderStatus;import sohal.lld.zerodha.enums.OrderType;import sohal.lld.zerodha.exception.InsufficientBalanceException;import sohal.lld.zerodha.order.Order;import sohal.lld.zerodha.user.Account;public class BuyOrderCommand implements OrderCommand {    private final Account account;    private final Order order;    private final StockExchange stockExchange;    public BuyOrderCommand(Account account, Order order) {        this.account = account;        this.order = order;        this.stockExchange = StockExchange.getInstance();    }    @Override    public void execute() {        double estimatedCost = order.getQuantity() * order.getPrice();        if (order.getOrderType() == OrderType.LIMIT && account.getBalance() < estimatedCost) {            throw new InsufficientBalanceException("Insufficient balance");        }        System.out.printf("Placing BUY order %s for %d shares of %s.%n", order.getOrderId(), order.getQuantity(), order.getStock().getSymbol());        stockExchange.placeBuyOrder(order);    }}